def transform(grid):
    """Rotate each 2x2 block's four diagonal marker colors one corner clockwise,
    then extend each color outward along its diagonal to the grid edge."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if grid[r][c] == grid[r][c+1] == grid[r+1][c] == grid[r+1][c+1] == 2:
                blocks.append((r, c))
    for r, c in blocks:
        # Halo colors in TL, TR, BL, BR order.
        tl, tr = grid[r-1][c-1], grid[r-1][c+2]
        bl, br = grid[r+2][c-1], grid[r+2][c+2]
        rays = [
            (r-1, c-1, -1, -1, bl),  # bottom-left -> top-left ray
            (r-1, c+2, -1,  1, tl),  # top-left -> top-right ray
            (r+2, c-1,  1, -1, br),  # bottom-right -> bottom-left ray
            (r+2, c+2,  1,  1, tr),  # top-right -> bottom-right ray
        ]
        for rr, cc, dr, dc, color in rays:
            while 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
                nr, nc = rr + dr, cc + dc
                # Stop before a square blocks or touches the next diagonal step.
                occupied = {(br0 + dr0, bc0 + dc0)
                            for br0, bc0 in blocks
                            for dr0 in (0, 1) for dc0 in (0, 1)}
                if any(pos in occupied for pos in ((nr, nc), (nr, cc), (rr, nc))):
                    break
                rr, cc = nr, nc
    return out

